template <bool B>
inline bool VerifyRFMUnion(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, RFMUnion type) {
  switch (type) {
    case RFMUnion::NONE: {
      return true;
    }
    case RFMUnion::CelestialFrameWrapper: {
      auto ptr = reinterpret_cast<const CelestialFrameWrapper *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RFMUnion::SpacecraftFrameWrapper: {
      auto ptr = reinterpret_cast<const SpacecraftFrameWrapper *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RFMUnion::OrbitFrameWrapper: {
      auto ptr = reinterpret_cast<const OrbitFrameWrapper *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RFMUnion::CustomFrameWrapper: {
      auto ptr = reinterpret_cast<const CustomFrameWrapper *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyRFMUnionVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<RFMUnion> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyRFMUnion(
        verifier,  values->Get(i), types->GetEnum<RFMUnion>(i))) {
      return false;
    }
  }
  return true;
}

inline void *RFMUnionUnion::UnPack(const void *obj, RFMUnion type, const ::flatbuffers::resolver_function_t *resolver) {
  (void)resolver;
  switch (type) {
    case RFMUnion::CelestialFrameWrapper: {
      auto ptr = reinterpret_cast<const CelestialFrameWrapper *>(obj);
      return ptr->UnPack(resolver);
    }
    case RFMUnion::SpacecraftFrameWrapper: {
      auto ptr = reinterpret_cast<const SpacecraftFrameWrapper *>(obj);
      return ptr->UnPack(resolver);
    }
    case RFMUnion::OrbitFrameWrapper: {
      auto ptr = reinterpret_cast<const OrbitFrameWrapper *>(obj);
      return ptr->UnPack(resolver);
    }
    case RFMUnion::CustomFrameWrapper: {
      auto ptr = reinterpret_cast<const CustomFrameWrapper *>(obj);
      return ptr->UnPack(resolver);
    }
    default: return nullptr;
  }
}

inline ::flatbuffers::Offset<void> RFMUnionUnion::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const ::flatbuffers::rehasher_function_t *_rehasher) const {
  (void)_rehasher;
  switch (type) {
    case RFMUnion::CelestialFrameWrapper: {
      auto ptr = reinterpret_cast<const CelestialFrameWrapperT *>(value);
      return CreateCelestialFrameWrapper(_fbb, ptr, _rehasher).Union();
    }
    case RFMUnion::SpacecraftFrameWrapper: {
      auto ptr = reinterpret_cast<const SpacecraftFrameWrapperT *>(value);
      return CreateSpacecraftFrameWrapper(_fbb, ptr, _rehasher).Union();
    }
    case RFMUnion::OrbitFrameWrapper: {
      auto ptr = reinterpret_cast<const OrbitFrameWrapperT *>(value);
      return CreateOrbitFrameWrapper(_fbb, ptr, _rehasher).Union();
    }
    case RFMUnion::CustomFrameWrapper: {
      auto ptr = reinterpret_cast<const CustomFrameWrapperT *>(value);
      return CreateCustomFrameWrapper(_fbb, ptr, _rehasher).Union();
    }
    default: return 0;
  }
}

inline RFMUnionUnion::RFMUnionUnion(const RFMUnionUnion &u) : type(u.type), value(nullptr) {
  switch (type) {
    case RFMUnion::CelestialFrameWrapper: {
      value = new CelestialFrameWrapperT(*reinterpret_cast<CelestialFrameWrapperT *>(u.value));
      break;
    }
    case RFMUnion::SpacecraftFrameWrapper: {
      value = new SpacecraftFrameWrapperT(*reinterpret_cast<SpacecraftFrameWrapperT *>(u.value));
      break;
    }
    case RFMUnion::OrbitFrameWrapper: {
      value = new OrbitFrameWrapperT(*reinterpret_cast<OrbitFrameWrapperT *>(u.value));
      break;
    }
    case RFMUnion::CustomFrameWrapper: {
      value = new CustomFrameWrapperT(*reinterpret_cast<CustomFrameWrapperT *>(u.value));
      break;
    }
    default:
      break;
  }
}

inline void RFMUnionUnion::Reset() {
  switch (type) {
    case RFMUnion::CelestialFrameWrapper: {
      auto ptr = reinterpret_cast<CelestialFrameWrapperT *>(value);
      delete ptr;
      break;
    }
    case RFMUnion::SpacecraftFrameWrapper: {
      auto ptr = reinterpret_cast<SpacecraftFrameWrapperT *>(value);
      delete ptr;
      break;
    }
    case RFMUnion::OrbitFrameWrapper: {
      auto ptr = reinterpret_cast<OrbitFrameWrapperT *>(value);
      delete ptr;
      break;
    }
    case RFMUnion::CustomFrameWrapper: {
      auto ptr = reinterpret_cast<CustomFrameWrapperT *>(value);
      delete ptr;
      break;
    }
    default: break;
  }
  value = nullptr;
  type = RFMUnion::NONE;
}

inline const CDM *GetCDM(const void *buf) {
  return ::flatbuffers::GetRoot<CDM>(buf);
}

inline const CDM *GetSizePrefixedCDM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<CDM>(buf);
}

inline const char *CDMIdentifier() {
  return "$CDM";
}

inline bool CDMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, CDMIdentifier());
}

inline bool SizePrefixedCDMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, CDMIdentifier(), true);
}

template <bool B = false>
inline bool VerifyCDMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<CDM>(CDMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedCDMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<CDM>(CDMIdentifier());
}

inline void FinishCDMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<CDM> root) {
  fbb.Finish(root, CDMIdentifier());
}

inline void FinishSizePrefixedCDMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<CDM> root) {
  fbb.FinishSizePrefixed(root, CDMIdentifier());
}

inline std::unique_ptr<CDMT> UnPackCDM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<CDMT>(GetCDM(buf)->UnPack(res));
}

inline std::unique_ptr<CDMT> UnPackSizePrefixedCDM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<CDMT>(GetSizePrefixedCDM(buf)->UnPack(res));
}

